function relativeLastOnline(timestamp){const stamp=Number(timestamp)||0;if(!stamp)return 'Not yet online';const elapsed=Math.max(0,Date.now()-stamp),minutes=Math.floor(elapsed/60000);if(minutes<1)return 'Just now';const formatter=new Intl.RelativeTimeFormat(undefined,{numeric:'auto'});if(minutes<60)return formatter.format(-minutes,'minute');const hours=Math.floor(minutes/60);if(hours<24)return formatter.format(-hours,'hour');const days=Math.floor(hours/24);if(days<30)return formatter.format(-days,'day');return formatter.format(-Math.floor(days/30),'month')}
