const musicAudio=$('#musicAudio'),musicToggle=$('#musicToggle'),musicStatus=$('#musicStatus'),musicVolume=$('#musicVolume'),musicVolumeValue=$('#musicVolumeValue'),currentTrackName=$('#currentTrackName');
let currentTrackIndex=0;
const savedVolumeRaw=localStorage.getItem('nv_music_volume'),savedVolume=savedVolumeRaw===null?10:Number(savedVolumeRaw);
if(Number.isFinite(savedVolume)&&savedVolume>=0&&savedVolume<=100)musicVolume.value=String(savedVolume);
function renderTrack(){const track=soundtrack[currentTrackIndex];currentTrackName.textContent=track.name;currentTrackName.title=track.name;musicAudio.src=track.file;musicAudio.load()}
function setMusicStatus(text){musicStatus.textContent=text}
async function playMusic(){try{await musicAudio.play();musicToggle.textContent='Pause';musicToggle.setAttribute('aria-label','Pause music');setMusicStatus('Now playing')}catch{musicToggle.textContent='Play';musicToggle.setAttribute('aria-label','Play music');setMusicStatus('Audio unavailable or waiting for playback permission')}}
musicAudio.volume=Number(musicVolume.value)/100;musicVolumeValue.textContent=`${musicVolume.value}%`;
musicToggle.addEventListener('click',()=>{if(musicAudio.paused)playMusic();else{musicAudio.pause();musicToggle.textContent='Play';musicToggle.setAttribute('aria-label','Play music');setMusicStatus('Paused')}});
$('#musicSkip').addEventListener('click',()=>{currentTrackIndex=(currentTrackIndex+1)%soundtrack.length;renderTrack();playMusic()});
musicVolume.addEventListener('input',()=>{const value=Number(musicVolume.value);musicAudio.volume=value/100;musicVolumeValue.textContent=`${value}%`;localStorage.setItem('nv_music_volume',String(value))});
musicAudio.addEventListener('ended',()=>{if(currentTrackIndex<soundtrack.length-1){currentTrackIndex++;renderTrack();playMusic()}else{musicToggle.textContent='Play';musicToggle.setAttribute('aria-label','Play music');setMusicStatus('Playlist ended')}});
musicAudio.addEventListener('error',()=>{musicToggle.textContent='Play';musicToggle.setAttribute('aria-label','Play music');setMusicStatus('Audio file unavailable')});
musicAudio.addEventListener('play',()=>{musicToggle.textContent='Pause';musicToggle.setAttribute('aria-label','Pause music');setMusicStatus('Now playing')});
musicAudio.addEventListener('pause',()=>{musicToggle.textContent='Play';musicToggle.setAttribute('aria-label','Play music');if(!musicAudio.ended)setMusicStatus('Paused')});
renderTrack();playMusic();
